using System.Globalization;
using System.Text;

namespace CoreIdml.AbiGen;

/// <summary>
/// Writes the low-level layer of each binding from the ABI definition. Each emitter owns the mapping from a
/// <see cref="AbiType"/> to its language; the idiomatic API on top (documents, exceptions, disposal) is hand-written
/// in each binding and only uses what is emitted here.
/// </summary>
public static class Emitters
{
    private const string Notice =
        "Generated by tools/CoreIdml.AbiGen from include/coreidml.h. Do not edit: change the header and run\n" +
        "`dotnet run --project tools/CoreIdml.AbiGen`.";

    /// <summary>Every generated file: path relative to the repository root, and content with LF line ends.</summary>
    public static IReadOnlyDictionary<string, string> Generate(AbiDefinition abi)
    {
        ArgumentNullException.ThrowIfNull(abi);
        return new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["bindings/node/src/abi.generated.ts"] = NodeTypeScript(abi),
            ["bindings/wasm/src/abi.generated.ts"] = WasmTypeScript(abi),
            ["bindings/python/src/coreidml/_abi.py"] = Python(abi),
            ["bindings/dart/coreidml/lib/src/ffi/bindings.g.dart"] = Dart(abi),
        };
    }

    // ---- TypeScript -------------------------------------------------------------------------------------------

    private static string NodeTypeScript(AbiDefinition abi)
    {
        var text = new StringBuilder();
        AppendTypeScriptHeader(text, abi);
        text.Append("/** A pointer as koffi hands it over; opaque here, read with the helpers in native.ts. NULL is null. */\n");
        text.Append("export type Pointer = unknown;\n\n");
        text.Append("/** An out parameter: koffi writes the value into the single slot. */\n");
        text.Append("export type Out<T> = [T];\n\n");

        text.Append("/** The koffi prototype of every function in coreidml.h. */\n");
        text.Append("export const PROTOTYPES = {\n");
        foreach (var function in abi.Functions)
        {
            var parameters = string.Join(", ", function.Parameters.Select(p => KoffiParameter(p)));
            text.Append(CultureInfo.InvariantCulture, $"  {Naming.Camel(function.Words)}: '{KoffiReturn(function.ReturnType)}{function.CName}({parameters})',\n");
        }
        text.Append("} as const;\n\n");

        text.Append("/** The C API as koffi binds it: one JavaScript function per C function. */\n");
        text.Append("export interface NativeFunctions {\n");
        foreach (var function in abi.Functions)
        {
            AppendDocComment(text, function.Documentation, "  ");
            var parameters = string.Join(", ", function.Parameters.Select(p => $"{Naming.Camel(p.Words)}: {TypeScriptParameter(p.Type)}"));
            text.Append(CultureInfo.InvariantCulture, $"  {Naming.Camel(function.Words)}({parameters}): {TypeScriptReturn(function.ReturnType)};\n");
        }
        text.Append("}\n");
        return text.ToString();
    }

    private static string WasmTypeScript(AbiDefinition abi)
    {
        var text = new StringBuilder();
        AppendTypeScriptHeader(text, abi);
        return text.ToString().TrimEnd('\n') + "\n";
    }

    private static void AppendTypeScriptHeader(StringBuilder text, AbiDefinition abi)
    {
        text.Append("// <auto-generated>\n");
        foreach (var line in Notice.Split('\n'))
        {
            text.Append(CultureInfo.InvariantCulture, $"//   {line}\n");
        }
        text.Append("// </auto-generated>\n\n");
        text.Append("/** `COREIDML_ABI_VERSION` of the header this file was generated from. */\n");
        text.Append(CultureInfo.InvariantCulture, $"export const ABI_VERSION = {abi.Version};\n\n");
        text.Append("/** Status codes of the library (`COREIDML_OK`, `COREIDML_ERR_*`). */\n");
        text.Append("export const Status = {\n");
        foreach (var status in abi.Statuses)
        {
            text.Append(CultureInfo.InvariantCulture, $"  {Naming.Camel(status.Words)}: {status.Value},\n");
        }
        text.Append("} as const;\n\n");
        text.Append("/** One of the {@link Status} values. */\n");
        text.Append("export type StatusCode = (typeof Status)[keyof typeof Status];\n\n");
    }

    private static string KoffiReturn(AbiType type) => type switch
    {
        AbiType.Nothing => "void ",
        AbiType.Number => "int32_t ",
        AbiType.Text => "const char *",
        _ => throw Unsupported(type, "a return type", "TypeScript"),
    };

    private static string KoffiParameter(AbiParameter parameter) => parameter.Type switch
    {
        AbiType.Number => $"int32_t {parameter.Name}",
        AbiType.Length => $"size_t {parameter.Name}",
        AbiType.Text => $"const char *{parameter.Name}",
        AbiType.Data => $"const uint8_t *{parameter.Name}",
        // Out pointers are declared as void** so the address comes back untouched and can be freed by the library.
        AbiType.TextOut or AbiType.DataOut => $"_Out_ void **{parameter.Name}",
        AbiType.LengthOut => $"_Out_ size_t *{parameter.Name}",
        AbiType.Memory => $"void *{parameter.Name}",
        AbiType.Document => $"intptr_t {parameter.Name}",
        AbiType.DocumentOut => $"_Out_ intptr_t *{parameter.Name}",
        AbiType.Nothing => throw Unsupported(parameter.Type, "a parameter", "TypeScript"),
    };

    private static string TypeScriptReturn(AbiType type) => type switch
    {
        AbiType.Nothing => "void",
        AbiType.Number => "number",
        AbiType.Text => "string | null",
        _ => throw Unsupported(type, "a return type", "TypeScript"),
    };

    private static string TypeScriptParameter(AbiType type) => type switch
    {
        AbiType.Number or AbiType.Length or AbiType.Document => "number",
        AbiType.Text => "string",
        AbiType.Data => "Uint8Array | null",
        AbiType.TextOut or AbiType.DataOut => "Out<Pointer>",
        AbiType.LengthOut or AbiType.DocumentOut => "Out<number | bigint>",
        AbiType.Memory => "Pointer",
        AbiType.Nothing => throw Unsupported(type, "a parameter", "TypeScript"),
    };

    // ---- Python -----------------------------------------------------------------------------------------------

    private static string Python(AbiDefinition abi)
    {
        var text = new StringBuilder();
        text.Append("# <auto-generated>\n");
        foreach (var line in Notice.Split('\n'))
        {
            text.Append(CultureInfo.InvariantCulture, $"#   {line}\n");
        }
        text.Append("# </auto-generated>\n");
        text.Append("\"\"\"ctypes signatures of the C API (include/coreidml.h).\"\"\"\n\n");
        text.Append("import ctypes\nimport enum\n\n");
        text.Append("#: COREIDML_ABI_VERSION of the header this file was generated from.\n");
        text.Append(CultureInfo.InvariantCulture, $"ABI_VERSION = {abi.Version}\n\n\n");
        text.Append("class Status(enum.IntEnum):\n");
        text.Append("    \"\"\"Status codes of the library (COREIDML_OK, COREIDML_ERR_*).\"\"\"\n\n");
        foreach (var status in abi.Statuses)
        {
            text.Append(CultureInfo.InvariantCulture, $"    {Naming.UpperSnake(status.Words)} = {status.Value}\n");
        }
        text.Append("\n\n#: Every function of coreidml.h: name -> (restype, argtypes).\n");
        text.Append("SIGNATURES = {\n");
        foreach (var function in abi.Functions)
        {
            var arguments = string.Join(", ", function.Parameters.Select(p => PythonType(p.Type)));
            if (function.Parameters.Count == 1)
            {
                arguments += ",";
            }
            text.Append(CultureInfo.InvariantCulture, $"    \"{function.CName}\": ({PythonType(function.ReturnType)}, ({arguments})),\n");
        }
        text.Append("}\n");
        return text.ToString();
    }

    private static string PythonType(AbiType type) => type switch
    {
        AbiType.Nothing => "None",
        AbiType.Number => "ctypes.c_int32",
        AbiType.Length => "ctypes.c_size_t",
        // c_char_p takes a bytes object without copying it; embedded NUL bytes are fine because the length travels separately.
        AbiType.Text or AbiType.Data => "ctypes.c_char_p",
        // Out pointers are void* so the address comes back untouched and can be freed by the library.
        AbiType.TextOut or AbiType.DataOut => "ctypes.POINTER(ctypes.c_void_p)",
        AbiType.LengthOut => "ctypes.POINTER(ctypes.c_size_t)",
        AbiType.Memory => "ctypes.c_void_p",
        AbiType.Document => "ctypes.c_ssize_t",
        AbiType.DocumentOut => "ctypes.POINTER(ctypes.c_ssize_t)",
    };

    // ---- Dart -------------------------------------------------------------------------------------------------

    private static string Dart(AbiDefinition abi)
    {
        var text = new StringBuilder();
        text.Append("// <auto-generated>\n");
        foreach (var line in Notice.Split('\n'))
        {
            text.Append(CultureInfo.InvariantCulture, $"//   {line}\n");
        }
        text.Append("// </auto-generated>\n");
        text.Append("// ignore_for_file: type=lint\n\n");
        text.Append("import 'dart:ffi';\n\nimport 'package:ffi/ffi.dart';\n\n");
        text.Append("/// `COREIDML_ABI_VERSION` of the header this file was generated from.\n");
        text.Append(CultureInfo.InvariantCulture, $"const int coreIdmlAbiVersion = {abi.Version};\n\n");
        text.Append("/// Status codes of the library (`COREIDML_OK`, `COREIDML_ERR_*`).\n");
        text.Append("abstract final class CoreIdmlStatus {\n");
        foreach (var status in abi.Statuses)
        {
            text.Append(CultureInfo.InvariantCulture, $"  static const int {Naming.Camel(status.Words)} = {status.Value};\n");
        }
        text.Append("}\n\n");

        // A function of the shape void f(coreidml_document) can release a document from a NativeFinalizer.
        var finalizers = abi.Functions.Where(f => f.ReturnType == AbiType.Nothing && f.Parameters is [{ Type: AbiType.Document }]).ToList();

        text.Append("/// The functions of coreidml.h, looked up in a loaded library.\n");
        text.Append("final class CoreIdmlBindings {\n");
        text.Append("  CoreIdmlBindings(DynamicLibrary library)\n");
        List<string> initializers = [];
        foreach (var function in abi.Functions)
        {
            var native = $"{DartNative(function.ReturnType)} Function({string.Join(", ", function.Parameters.Select(p => DartNative(p.Type)))})";
            initializers.Add($"{Naming.Camel(function.Words)} = library.lookupFunction<{native}, {DartSignature(function)}>('{function.CName}')");
        }
        foreach (var function in finalizers)
        {
            initializers.Add($"{Naming.Camel(function.Words)}Finalizer = library.lookup<NativeFinalizerFunction>('{function.CName}')");
        }
        for (var i = 0; i < initializers.Count; i++)
        {
            text.Append(CultureInfo.InvariantCulture, $"      {(i == 0 ? ':' : ' ')} {initializers[i]}{(i == initializers.Count - 1 ? ';' : ',')}\n");
        }
        foreach (var function in abi.Functions)
        {
            text.Append('\n');
            foreach (var line in function.Documentation)
            {
                text.Append(CultureInfo.InvariantCulture, $"  ///{(line.Length == 0 ? "" : " " + line)}\n");
            }
            text.Append(CultureInfo.InvariantCulture, $"  final {DartSignature(function)} {Naming.Camel(function.Words)};\n");
        }
        foreach (var function in finalizers)
        {
            text.Append(CultureInfo.InvariantCulture, $"\n  /// `{function.CName}` as a native finalizer: an intptr_t argument is passed like a pointer.\n");
            text.Append(CultureInfo.InvariantCulture, $"  final Pointer<NativeFinalizerFunction> {Naming.Camel(function.Words)}Finalizer;\n");
        }
        text.Append("}\n");
        return text.ToString();
    }

    private static string DartSignature(AbiFunction function) =>
        $"{DartType(function.ReturnType)} Function({string.Join(", ", function.Parameters.Select(p => $"{DartType(p.Type)} {Naming.Camel(p.Words)}"))})";

    private static string DartNative(AbiType type) => type switch
    {
        AbiType.Nothing => "Void",
        AbiType.Number => "Int32",
        AbiType.Length => "Size",
        AbiType.Document => "IntPtr",
        _ => DartType(type),
    };

    private static string DartType(AbiType type) => type switch
    {
        AbiType.Nothing => "void",
        AbiType.Number or AbiType.Length or AbiType.Document => "int",
        AbiType.Text => "Pointer<Utf8>",
        AbiType.TextOut => "Pointer<Pointer<Utf8>>",
        AbiType.Data => "Pointer<Uint8>",
        AbiType.DataOut => "Pointer<Pointer<Uint8>>",
        AbiType.LengthOut => "Pointer<Size>",
        AbiType.Memory => "Pointer<Void>",
        AbiType.DocumentOut => "Pointer<IntPtr>",
    };

    // ---- shared -----------------------------------------------------------------------------------------------

    private static void AppendDocComment(StringBuilder text, IReadOnlyList<string> lines, string indent)
    {
        if (lines.Count == 0)
        {
            return;
        }
        if (lines.Count == 1)
        {
            text.Append(CultureInfo.InvariantCulture, $"{indent}/** {lines[0]} */\n");
            return;
        }
        text.Append(CultureInfo.InvariantCulture, $"{indent}/**\n");
        foreach (var line in lines)
        {
            text.Append(CultureInfo.InvariantCulture, $"{indent} *{(line.Length == 0 ? "" : " " + line)}\n");
        }
        text.Append(CultureInfo.InvariantCulture, $"{indent} */\n");
    }

    private static NotSupportedException Unsupported(AbiType type, string role, string language) =>
        new($"{type} as {role} is not mapped for {language} yet; add it to Emitters.cs.");
}
